"use client";

import { motion } from "framer-motion";
import { Calendar, Hash, School, Globe, Users, Download, Share2, CheckCircle, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { formatDateReadable } from "@/lib/utils";
import Image from "next/image";
import { GlareCard } from "@/components/ui/glare-card";

type CertificateData = {
  certificate_id: string;
  participant_name: string;
  school: string;
  certificate_type: string;
  event: string | null;
  event_code: string | null;
  date_issued: string;
  status: string;
  pdf_available: boolean;
  pdf_download_url: string | null;
  country?: string;
  committee?: string;
  segment?: string;
  team_name?: string;
  level?: string;
  [key: string]: any;
};

interface CertificateDisplayProps {
  certificate: CertificateData;
  valid?: boolean;
  revoked?: boolean;
  revokedInfo?: {
    revoked_at: string;
    revoked_reason: string;
  } | null;
}

export function CertificateDisplay({ certificate, valid = true, revoked = false, revokedInfo }: CertificateDisplayProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
      className="w-full max-w-3xl mx-auto"
    >
        {/* Status Banner */}
        <div className={`mb-6 p-4 rounded-lg border flex items-center gap-3 backdrop-blur-sm ${
            revoked 
                ? "bg-destructive/10 border-destructive/30 text-destructive" 
                : valid 
                    ? "bg-green-500/10 border-green-500/30 text-green-400" 
                    : "bg-yellow-500/10 border-yellow-500/30 text-yellow-400"
        }`}>
            {revoked ? <AlertTriangle className="h-5 w-5" /> : <CheckCircle className="h-5 w-5" />}
            <div>
                <p className="font-semibold">
                    {revoked ? "Certificate Revoked" : valid ? <span className="inline-block animate-shiny-text bg-clip-text text-transparent bg-[length:250%_auto]" style={{ backgroundImage: 'linear-gradient(90deg, #4ade80 0%, #4ade80 40%, #ffffff 50%, #4ade80 60%, #4ade80 100%)' }}>Verified</span> : "Verification Pending"}
                </p>
                {revoked && revokedInfo && (
                    <p className="text-sm opacity-90 mt-1">
                        Revoked on {formatDateReadable(revokedInfo.revoked_at)}: {revokedInfo.revoked_reason}
                    </p>
                )}
            </div>
        </div>

        {/* Main Info Card */}
        <GlareCard className="bg-forest-900/40 border border-accent-gold/20 rounded-xl backdrop-blur-md shadow-xl relative">
            {/* Background Logo Watermark */}
            <div className="absolute top-0 right-0 p-8 opacity-[0.03] pointer-events-none">
                <Image 
                    src="/logo.png" 
                    alt="IGACMUN Logo" 
                    width={300} 
                    height={300} 
                    className="object-contain"
                />
            </div>

            {/* Header Section */}
            <div className="p-8 border-b border-accent-gold/10 text-center md:text-left relative z-10">
                <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-6">
                    <div className="flex-1">
                        <h2 className="text-3xl md:text-4xl font-bold text-white mb-2 leading-tight">
                            {certificate.participant_name}
                        </h2>
                        
                        {certificate.school && (
                            <div className="flex items-center justify-center md:justify-start gap-2 text-muted-foreground mb-4">
                                <School className="h-4 w-4 text-accent-gold/70" />
                                {certificate.school}
                            </div>
                        )}

                        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-accent-gold/10 border border-accent-gold/20 text-accent-gold text-xs font-medium tracking-wider uppercase">
                            {certificate.certificate_type}
                        </div>
                    </div>

                    {/* Logo in Header */}
                    <div className="hidden md:block flex-shrink-0">
                        <div className="w-20 h-20 relative">
                            <Image 
                                src="/logo.png" 
                                alt="IGACMUN Logo" 
                                fill
                                className="object-contain drop-shadow-[0_0_15px_rgba(198,168,88,0.2)]"
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* Additional Info Section (Conditional) */}
            {(certificate.committee || certificate.country || certificate.team_name || certificate.segment || certificate.level) && (
                <div className="px-8 py-6 border-b border-accent-gold/10 bg-forest-950/20">
                    <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-4 flex items-center gap-2">
                        <Users className="h-3 w-3 text-accent-gold" /> Participation Details
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {certificate.committee && (
                            <div className="flex justify-between items-center p-3 rounded-lg bg-forest-900/40 border border-white/5">
                                <span className="text-sm text-muted-foreground">Committee</span>
                                <span className="text-sm font-medium text-foreground">{certificate.committee}</span>
                            </div>
                        )}
                        {certificate.country && (
                            <div className="flex justify-between items-center p-3 rounded-lg bg-forest-900/40 border border-white/5">
                                <span className="text-sm text-muted-foreground">Country</span>
                                <span className="text-sm font-medium text-foreground">{certificate.country}</span>
                            </div>
                        )}
                        {certificate.team_name && (
                            <div className="flex justify-between items-center p-3 rounded-lg bg-forest-900/40 border border-white/5">
                                <span className="text-sm text-muted-foreground">Team</span>
                                <span className="text-sm font-medium text-foreground">{certificate.team_name}</span>
                            </div>
                        )}
                        {certificate.segment && (
                            <div className="flex justify-between items-center p-3 rounded-lg bg-forest-900/40 border border-white/5">
                                <span className="text-sm text-muted-foreground">Segment</span>
                                <span className="text-sm font-medium text-foreground">{certificate.segment}</span>
                            </div>
                        )}
                        {certificate.level && (
                            <div className="flex justify-between items-center p-3 rounded-lg bg-forest-900/40 border border-white/5">
                                <span className="text-sm text-muted-foreground">Level</span>
                                <span className="text-sm font-medium text-foreground capitalize">{certificate.level}</span>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Verification Details */}
            <div className="p-8 grid gap-6 sm:grid-cols-2">
                <div>
                    <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2 flex items-center gap-2">
                        <Hash className="h-3 w-3 text-accent-gold" /> Verification ID
                    </h3>
                    <div className="bg-forest-950/30 rounded-lg p-3 border border-white/5">
                        <code className="text-accent-gold font-mono text-lg tracking-wide">{certificate.certificate_id}</code>
                    </div>
                </div>

                <div>
                    <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2 flex items-center gap-2">
                        <Calendar className="h-3 w-3 text-accent-gold" /> Date Issued
                    </h3>
                    <div className="bg-forest-950/30 rounded-lg p-3 border border-white/5">
                        <p className="text-foreground font-medium">{formatDateReadable(certificate.date_issued)}</p>
                    </div>
                </div>
            </div>

            {/* Actions Footer */}
            <div className="p-6 bg-forest-950/40 border-t border-white/5 flex flex-col sm:flex-row gap-4 justify-end">
                 <Button
                  onClick={() => {
                    navigator.clipboard.writeText(
                      `${window.location.origin}/certificate-portal/${certificate.certificate_id}`
                    );
                    alert("Link copied!");
                  }}
                  variant="outline"
                  className="border-accent-gold/20 hover:bg-accent-gold/10 text-accent-gold"
                >
                  <Share2 className="h-4 w-4 mr-2" />
                  Share Verification
                </Button>
                
                {certificate.pdf_available && certificate.pdf_download_url && (
                  <Button
                    onClick={() => window.open(certificate.pdf_download_url!, "_blank")}
                    className="bg-accent-gold hover:bg-accent-gold/90 text-forest-950"
                  >
                    <Download className="h-4 w-4 mr-2" />
                    Download Original PDF
                  </Button>
                )}
            </div>
        </GlareCard>
    </motion.div>
  );
}
