'use server'

import { createClient } from '@/lib/supabase/server'

export interface Certificate {
  id: string
  certificate_id: string
  participant_name: string
  school: string
  certificate_type: string
  date_issued: string
  created_at: string
  event?: string | null
  event_code?: string | null
  status?: string
  pdf_available?: boolean
  pdf_download_url?: string | null
  country?: string
  committee?: string
  segment?: string
  team_name?: string
  revoked_at?: string
  revoked_reason?: string
  [key: string]: any
}

export async function searchCertificate(query: string): Promise<{ success: boolean; data?: Certificate[]; error?: string }> {
  if (!query) {
    return { success: false, error: 'Please enter a certificate ID' }
  }

  const supabase = await createClient()

  try {
    // Search ONLY by certificate_id (exact match)
    const { data: certificate, error } = await supabase
      .from('certificates')
      .select(`
        *,
        events (*),
        certificate_metadata (*)
      `)
      .eq('certificate_id', query)
      .single()

    if (error || !certificate) {
      return { success: false, error: 'Certificate not found. Please check the ID and try again.' }
    }

    // Format the response similar to the API
    const metadata = (certificate.certificate_metadata || []).reduce((acc: any, meta: any) => {
      acc[meta.field_name] = meta.field_type === 'json' || meta.field_type === 'array' 
        ? JSON.parse(meta.field_value) 
        : meta.field_value
      return acc
    }, {})

    const formattedCertificate = {
      ...certificate,
      event: certificate.events?.event_name || null,
      event_code: certificate.events?.event_code || null,
      pdf_download_url: certificate.pdf_storage_path || null,
      ...metadata
    }

    // Log verification (optional for search, but good for consistency)
    // We can skip logging for simple search if we want to avoid side effects on every keystroke/search
    // But since this is a "Verify" action, we probably should log it.
    // However, headers() might not be available easily in server actions called from client in the same way.
    // Let's skip logging for now to keep it simple and fast.

    return { success: true, data: [formattedCertificate] }
  } catch (error) {
    console.error('Search error:', error)
    return { success: false, error: 'An unexpected error occurred' }
  }
}
